import wandb; api = wandb.Api()
# Just check top competitors
for agent in ['edward', 'violet', 'tanjiro', 'mitsuha', 'senku', 'guts', 'spike']:
    runs = api.runs('wandb-applied-ai-team/kagent-v1', filters={'tags': 'score', 'display_name': {'\$regex': f'^score/{agent}/'}}, order='+summary_metrics.test/overall/mae_surf_p', per_page=1)
    if runs:
        mae = runs[0].summary.get('test/overall/mae_surf_p', '?')
        marker = ' <-- ME' if agent == 'edward' else ''
        print(f'{agent:15s}: {mae:.2f}{marker}' if isinstance(mae, float) else f'{agent}: {mae}')
" 2>/dev/null

